        {te = p;p--;{ FoundSyllable(info, ts, te, ConsonantSyllable, ref syllable_serial); }}
        break;
        case 9:
        {te = p;p--;{ FoundSyllable(info, ts, te, BrokenCluster, ref syllable_serial); buffer.ScratchFlags |= LayoutBuffer.ScratchHasBrokenSyllable; }}
        break;
        case 12:
        {te = p;p--;{ FoundSyllable(info, ts, te, NonMyanmarCluster, ref syllable_serial); }}
        break;
        case 11:
        {    switch( act ) {
        case 2:
        {{p = ((te))-1;} FoundSyllable(info, ts, te, NonMyanmarCluster, ref syllable_serial); }
        break;
        case 3:
        {{p = ((te))-1;} FoundSyllable(info, ts, te, BrokenCluster, ref syllable_serial); buffer.ScratchFlags |= LayoutBuffer.ScratchHasBrokenSyllable; }
        break;
        }
        }
        break;
        case 6:
        {te = p+1;}
        {act = 2;}
        break;
        case 5:
        {te = p+1;}
        {act = 3;}
        break;
        }

    _again:
        switch ( to_state_actions[cs] ) {
        case 1:
        {ts = 0;}
        break;
        }

        if ( ++p != pe )
            goto _resume;
        _test_eof:
        if ( p == eof )
        {
        if ( eof_trans[cs] > 0 ) {
            _trans = eof_trans[cs] - 1;
            goto _eof_trans;
        }
        }

        }
        _ = act;
        _ = ts;
    }

    private static void FoundSyllable(GlyphInfo[] info, int ts, int te, int syllableType, ref int serial)
    {
        for (int i = ts; i < te; i++)
        {
            info[i].Syllable = (byte)((serial << 4) | syllableType);
        }

        serial++;
        if (serial == 16)
        {
            serial = 1;
        }
    }
}
